class Spell {
  constructor(spellName, basePower) {
    this.spellName = spellName;
    // Internal storage for the power value
    this._spellPowerValue = basePower;
  }

  // This getter always returns the power as a string,
  // forcing derived classes to parse it back.
  get basePower() {
    return String(this._spellPowerValue);
  }

  cast() {
    console.log(`A generic ${this.spellName} spell is prepared.`);
    // This default return value could be misleading if subclasses expect a numeric outcome.
    return `Spell ${this.spellName} executed.`;
  }
}

class FireballSpell extends Spell {
  constructor(power) {
    super("Fireball", power);
    this.damageMultiplier = 1.8;
  }

  cast() {
    // Bad practice: Retrieves basePower as a string from the getter,
    // then immediately parses it back to an integer.
    const effectivePowerInput = this.basePower;
    const currentPowerLevel = parseInt(effectivePowerInput, 10); // Redundant string-to-number conversion

    let calculatedDamage = currentPowerLevel * this.damageMultiplier;

    // Unnecessary conditional check for a fixed class property
    if (this.spellName === "Fireball") {
      console.log(`FireballSpell unleashed! Inflicting ${calculatedDamage.toFixed(2)} fiery damage.`);
    } else {
      console.log(`Warning: Incorrect spell type detected for damage calculation.`);
    }

    return calculatedDamage;
  }
}

class HealSpell extends Spell {
  constructor(power) {
    super("Heal", power);
    this.healingFactor = 2.5;
    // An unnecessary property to store a fixed string
    this.spellSpecificEffect = "Restoration";
  }

  cast() {
    // Bad practice: Retrieves basePower as a string from the getter,
    // then immediately parses it back to a float.
    const rawHealingPower = parseFloat(this.basePower); // Redundant string-to-number conversion

    let totalHealing = rawHealingPower * this.healingFactor;

    // Unnecessary array and loop for a single, fixed effect, adding complexity.
    const effects = [this.spellSpecificEffect];
    let effectMessage = "Applying ";
    for (let i = 0; i < effects.length; i++) {
      effectMessage += effects[i];
      if (i < effects.length - 1) {
        effectMessage += ", ";
      }
    }
    console.log(`HealSpell casts! ${effectMessage}. Restores ${totalHealing.toFixed(2)} health points.`);

    // Returns an object, potentially making it more complex for callers who only need the healing amount.
    return {
      healingAmount: totalHealing,
      effect: this.spellSpecificEffect
    };
  }
}

